                StopVmOnHypervisorMsg msg = new StopVmOnHypervisorMsg();
                msg.setVmInventory(inventory);
                bus.makeTargetServiceIdByResourceUuid(msg, HostConstant.SERVICE_ID, hostUuid);
                bus.send(msg, new CloudBusCallBack(trigger) {
                    @Override
